{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Mebendazole, a benzimidazole-containing drug, has an absolute oral bioavailability of about 1% in humans, indicating that this heterocyclic core can be associated with very poor systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Flubendazole, another benzimidazole analogue, shows low oral bioavailability in humans, supporting the concern that the benzimidazole moiety in the query may limit absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Revefenacin, a large polar molecule with basic amine and amide functionalities, has an absolute oral bioavailability below 3% in humans, illustrating that high polarity and ionizable groups can cause very low oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "MR309, which contains both a morpholine and a pyrazole, was discontinued due to poor oral bioavailability in humans, directly supporting a low-F outcome for the query's morpholine-pyrazole combination.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Darifenacin has an oral bioavailability of only 15-19% in humans, below the 20% threshold, due to low solubility and high first-pass metabolism, consistent with the query's predicted absorption liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Tazemetostat, the closest analogue by Morgan similarity, has an absolute oral bioavailability of about 33.9% in humans despite containing a morpholinomethyl phenyl and hydroxyamidine motif; this is the strongest evidence for a possible high-F outcome.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C32"],
      "claim": "Entrectinib has a reported oral bioavailability greater than 50% in humans and contains morpholine and heteroaromatic amide features, providing some contradictory evidence for high bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (F < 20%) because the query is highly polar and zwitterionic with a very low neutral fraction, high TPSA, and multiple ionizable groups, and its benzimidazole/morpholine/pyrazole features align with several experimental low-bioavailability analogues. The closest analogue tazemetostat shows ~32% F, but its lower polarity and different heterocyclic core limit transferability; the query's additional polar/ionizable elements likely push F below the threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "All available analogues have low Morgan similarity (<0.28), limiting structural transferability.",
    "Some supplied records have apparent SMILES/name mismatches (e.g., fenofibrate/fenbendazole, R406) and were not used as reliable evidence.",
    "No permeability, efflux, or metabolic stability data are available for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

